<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class UploadBatch extends Model {protected $fillable=['uuid','group_id','user_id','state','total_files','pending_files','processing_files','completed_files','failed_files','cancelled_at'];protected $casts=['cancelled_at'=>'datetime'];public function files(){return $this->hasMany(UploadBatchFile::class);}public function group(){return $this->belongsTo(Group::class);}public function refreshCounts():void{$counts=$this->files()->selectRaw('state,count(*) aggregate')->groupBy('state')->pluck('aggregate','state');$failed=(int)($counts['failed']??0);$completed=(int)($counts['completed']??0);$processing=(int)($counts['processing']??0);$pending=(int)($counts['pending']??0)+(int)($counts['queued']??0);$state=$this->cancelled_at?'cancelled':($processing?'processing':($pending?'queued':($failed&&$completed?'partially_completed':($failed?'failed':'completed'))));$this->update(compact('state')+['pending_files'=>$pending,'processing_files'=>$processing,'completed_files'=>$completed,'failed_files'=>$failed]);}}
